(()=>{
const listIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M8 6h12M8 12h12M8 18h12M3 6h1M3 12h1M3 18h1"/></svg>';
const chatIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-6 3V6a2 2 0 0 1 2-2Z"/></svg>';
const originalKnowledge=knowledge;knowledge=function(){return originalKnowledge().replace('<nav class="app-rail" aria-label="Workspace navigation">','<nav class="app-rail" aria-label="Workspace navigation"><button data-chat="open" aria-label="Chat" title="Chat">'+chatIcon+'<small>Chat</small></button>')};
let scope='My team',directory=false;
const originalItems=companyItems;
companyItems=function(){const all=originalItems().map(r=>({...r,accuracy:knowledgeRecords.find(k=>k.id===r.id)?.pool?.accuracy,team:r.own?(knowledgeRecords.find(k=>k.id===r.id)?.pool?.team||'Payments team'):r.id==='example-1'?'Payments team':r.id==='example-3'?'Platform team':r.id==='example-4'?'Operations team':'Payroll team'}));return directory?all.filter(r=>scope==='Company'||scope==='My team'&&r.team==='Payments team'||scope==='Collaborating teams'&&['Platform team','Operations team'].includes(r.team)):all};
const originalDirectory=poolDirectory;poolDirectory=function(){directory=true;let html;try{html=originalDirectory()}finally{directory=false}return html.replace('<div class="pool-toolbar">',`<div class="pool-scope" role="group" aria-label="Knowledge scope">${['My team','Collaborating teams','Company'].map(t=>`<button data-wf-scope="${t}" aria-pressed="${scope===t}">${t}</button>`).join('')}</div><p class="scope-caption">${scope==='My team'?'Payments team':scope==='Collaborating teams'?'Platform & Operations · Teams you work with':'All teams across your company'}</p><div class="pool-toolbar">`)};
const originalDetail=poolDetail;poolDetail=function(r){return (r.accuracy&&r.accuracy!=='confirmed'?'<p class="scope-caption">AI-assisted draft · Not yet confirmed by its author</p>':'')+originalDetail(r)};
let permissions;try{permissions=JSON.parse(localStorage.getItem('capture-permissions-v1'))}catch{}permissions=permissions||{record:true,files:false,scope:'selected',folders:['Work projects']};
function persist(){localStorage.setItem('capture-permissions-v1',JSON.stringify(permissions))}
const originalApps=apps;apps=function(){return originalApps().replace('<div class="filterbar">',`<section class="capture-permissions"><h2>Capture permissions</h2><p>Applies to the applications selected below.</p><div class="permission-toggles"><label><input type="checkbox" data-permission="record" ${permissions.record?'checked':''}> Record screen activity</label><label><input type="checkbox" data-permission="files" ${permissions.files?'checked':''}> Read linked files</label></div>${permissions.files?`<div class="folder-scope"><label><input type="radio" name="folder-scope" data-folder-scope="all" ${permissions.scope==='all'?'checked':''}> All project folders</label><label><input type="radio" name="folder-scope" data-folder-scope="selected" ${permissions.scope==='selected'?'checked':''}> Choose folders</label>${permissions.scope==='selected'?`<div class="folder-options">${['Work projects','Research','Shared documentation'].map(f=>`<label><input type="checkbox" data-folder="${f}" ${permissions.folders.includes(f)?'checked':''}> ▱ ${f}</label>`).join('')}</div>`:'<small>Includes all three sample project folders.</small>'}</div>`:''}<small>Prototype permissions · No real screen or file access.</small></section><div class="filterbar">`)};
let savedTicket;try{savedTicket=JSON.parse(localStorage.getItem('demo-ticket-progress'))}catch{}
let step=savedTicket?.step||0,finished=!!savedTicket?.finished,ticketActive=!!savedTicket?.active,reminder=false,notice='Your daily knowledge summary is ready.';
let completed=new Set(savedTicket?.completed||[]);
function saveTicket(){localStorage.setItem('demo-ticket-progress',JSON.stringify({step,finished,active:ticketActive,completed:[...completed],code:state.code}))}
if(savedTicket?.code)state.code=savedTicket.code;
function milestone(id,title,summary){if(completed.has(id))return;completed.add(id);window.addStageKnowledge?.(id,title,summary);notice=title+' · Added to your list.';reminder=true;setUnread(true);state.agentCollapsed=false;saveTicket()}

let unread=localStorage.getItem('daily-list-unread')==='true';
function setUnread(value){unread=value;localStorage.setItem('daily-list-unread',String(value))}
function progress(){const labels=['Investigating','Implementing','Validating','Summarizing','Complete'];const current=finished?5:step+1;return `<section class="ticket-progress ticket-progress-minimal"><div class="ticket-progress-meter"><span>${current}/5</span><div class="ticket-track" role="progressbar" aria-label="Ticket progress" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${current}"><i style="width:${current*20}%"></i></div></div><div class="ticket-progress-step"><span>Current status</span><strong>${labels[current-1]}</strong></div></section>`}

const originalAgent=agent;agent=function(){let html=originalAgent();if(!state.agentCollapsed){html=html.replace('<nav class="agent-tools"',`${ticketActive?progress():''}${reminder?`<section class="agent-daily-note"><p>${esc(notice)}</p><div><button data-nb="review">View today’s list →</button><button data-daily-cancel>Cancel</button></div></section>`:''}<nav class="agent-tools"`);html=html.replace('<button data-action="agent-collapse"',`<button data-nb="review" title="Today’s knowledge" aria-label="Today’s knowledge list${unread?' · Unread':''}" class="daily-list-button">${listIcon}${unread?'<i class="daily-unread-dot" aria-hidden="true"></i>':''}</button><span class="separator"></span><button data-action="agent-collapse"`)}return html};
const originalLaunch=launchApp;launchApp=function(id){originalLaunch(id);if(id==='vscode'){ticketActive=true;saveTicket()}if(!permissions.record){state.recording=false;state.captureStarted=false}render()};
const originalToggle=toggleRecording;toggleRecording=function(){if(!permissions.record){toast('Enable screen recording in Settings first.');return}originalToggle()};
const originalRun=runExercise;runExercise=function(){originalRun();if(state.testResult?.passed){milestone('implementation','Implementation complete','Changed the arithmetic operator from subtraction to addition.');step=Math.max(step,3);milestone('validation','Validation complete','The positive, negative, and zero-input examples passed.')}saveTicket();render()};
const originalFinish=finishCapture;finishCapture=function(){if(finished)return;ticketActive=true;step=4;finished=true;originalFinish();milestone('summary','Capture complete','Work session summarized and saved for the daily review.');saveTicket();render()};
document.addEventListener('click',e=>{const scopeButton=e.target.closest('[data-wf-scope]');if(scopeButton){scope=scopeButton.dataset.wfScope;kb.poolItem=null;render()}if(e.target.closest('[data-action="apply-fix"]')){ticketActive=true;step=Math.max(step,2);milestone('investigation','Investigation complete','Identified subtraction where addition was expected.');milestone('implementation','Implementation complete','Changed the arithmetic operator from subtraction to addition.');saveTicket();render()}});
document.addEventListener('input',e=>{if(e.target.id==='practice-code'){ticketActive=true;step=Math.max(step,1);milestone('investigation','Investigation complete','Identified the operator in the addition function as the change to investigate.');saveTicket();const panel=document.querySelector('.desktop-agent');if(panel)panel.outerHTML=agent();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.permission){permissions[t.dataset.permission]=t.checked;if(!permissions.record){state.recording=false;state.captureStarted=false}persist();render()}if(t.dataset.folderScope){permissions.scope=t.dataset.folderScope;persist();render()}if(t.dataset.folder){permissions.folders=t.checked?[...new Set([...permissions.folders,t.dataset.folder])]:permissions.folders.filter(f=>f!==t.dataset.folder);persist()}});
function dailyReminder(){const day=new Date().toLocaleDateString('en-CA');if(new Date().getHours()>=17&&localStorage.getItem('daily-summary-seen')!==day&&state.screen==='desktop'){notice='Your daily knowledge summary is ready.';reminder=true;setUnread(true);state.agentCollapsed=false;localStorage.setItem('daily-summary-seen',day);render()}}
window.markDailyListRead=()=>{reminder=false;setUnread(false)};
document.addEventListener('click',e=>{if(e.target.closest('[data-daily-cancel]')){reminder=false;render();return}if(e.target.closest('[data-nb="review"]')){reminder=false;setUnread(false)}},true);
setInterval(dailyReminder,30000);
render();dailyReminder();
})();
